def compute(vars):
    total_debt = vars["v1"]
    debt_due_2018 = vars["v2"]

    if total_debt == 0:
        return None

    percentage = (debt_due_2018 / total_debt) * 100

    return {
        "value": percentage,
        "trace": {
            "total_debt": total_debt,
            "debt_due_2018": debt_due_2018,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
